import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.76ZGnlPi.js";const u=JSON.parse('{"title":"Carrier Balance (Supplier Ledger)","description":"","frontmatter":{},"headers":[],"relativePath":"admin/supplier-ledger/index.md","filePath":"admin/supplier-ledger/index.md"}'),n={name:"admin/supplier-ledger/index.md"};function r(o,e,d,h,c,l){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="carrier-balance-supplier-ledger" tabindex="-1">Carrier Balance (Supplier Ledger) <a class="header-anchor" href="#carrier-balance-supplier-ledger" aria-label="Permalink to &quot;Carrier Balance (Supplier Ledger)&quot;">​</a></h1><p>We hold a prepaid account with the OTA carrier. Every ticket issued draws it down, every carrier refund puts money back, and finance tops it up by bank transfer.</p><p><strong>The carrier publishes no endpoint for that balance</strong>, so this service keeps its own books:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>opening + deposits + carrier refunds - ticket issuance = balance</span></span></code></pre></div><p>The ledger is append-only. Nothing is ever edited or deleted; a correction is a new row.</p><div class="warning custom-block"><p class="custom-block-title">This balance never blocks anything</p><p>No code path refuses to ticket, and no write fails, because the balance is low or negative. The number is an <em>estimate</em> of the carrier&#39;s, and it cannot see every charge the carrier makes. Treating an estimate as a gate would turn a counting error into a customer who never receives a ticket, inside a 30-minute carrier deadline.</p></div><h2 id="reading-the-balance" tabindex="-1">Reading the balance <a class="header-anchor" href="#reading-the-balance" aria-label="Permalink to &quot;Reading the balance&quot;">​</a></h2><p><code>GET /api/v1/admin/supplier-ledger/balance</code></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;balanceSAR&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;38449.46&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;perKindSAR&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;OPENING&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;50000.00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;TICKET_ISSUE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;12496.79&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;entryCount&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">65</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;lastReconciledAt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-09-03T09:34:19.000Z&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Read <code>lastReconciledAt</code> before acting on the figure.</strong> Because the carrier has no balance endpoint, an export is uploaded by hand on no fixed schedule. Until that happens the balance is our arithmetic, not the carrier&#39;s. <code>null</code> means it has never been checked against the carrier at all.</p><p><code>GET /api/v1/admin/supplier-ledger/entries</code> lists movements, newest first, and takes <code>kind</code>, <code>from</code>, <code>to</code>, <code>pnr</code>, <code>bookingCode</code>, <code>bookingId</code>, <code>page</code> and <code>limit</code>.</p><p>Entries are ordered by <code>occurredAt</code> — when the carrier moved the money — which is not <code>createdAt</code>, when we recorded it. A carrier refund credits the account well after we mark a customer refund done.</p><p>Each row carries its booking&#39;s <code>bookingCode</code> and <code>otaBookingRef</code> (the PNR). The carrier writes its account export against the PNR, so that is the key to join the two sides on when building a comparison.</p><div class="warning custom-block"><p class="custom-block-title"><code>perKindSAR</code> is unsigned</p><p>It holds absolute sums, so <code>TICKET_ISSUE</code> reads <em>positive</em> there while the balance subtracts it. <code>kindDirections</code> in the same response says which way each kind moves the balance — read that instead of hardcoding the rule.</p></div><h2 id="entry-kinds" tabindex="-1">Entry kinds <a class="header-anchor" href="#entry-kinds" aria-label="Permalink to &quot;Entry kinds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Sign</th><th>Written by</th></tr></thead><tbody><tr><td><code>OPENING</code></td><td>+</td><td>An admin, once, to seed the balance</td></tr><tr><td><code>DEPOSIT</code></td><td>+</td><td>An admin, per top-up</td></tr><tr><td><code>TICKET_ISSUE</code></td><td>−</td><td>Automatically, when a booking&#39;s tickets are issued</td></tr><tr><td><code>REFUND_CREDIT</code></td><td>+</td><td>Automatically, when the carrier refunds a cancellation</td></tr><tr><td><code>ADJUSTMENT</code></td><td>±</td><td>An admin, for a movement with no row to derive it from</td></tr><tr><td><code>RECONCILE</code></td><td>±</td><td>An admin, from the carrier&#39;s own statement</td></tr></tbody></table><p><code>ADJUSTMENT</code> and <code>RECONCILE</code> are the only kinds whose amount may be negative, because a correction has to be able to go either way.</p><h2 id="recording-the-opening-balance" tabindex="-1">Recording the opening balance <a class="header-anchor" href="#recording-the-opening-balance" aria-label="Permalink to &quot;Recording the opening balance&quot;">​</a></h2><p>Do this once, before anything else.</p><p><code>POST /api/v1/admin/supplier-ledger/deposits</code></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;amountSAR&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;reference&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TRF-8157603042235842&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;occurredAt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-03-09T12:56:01.000Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;isOpeningBalance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;note&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Initial funding of the carrier account&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">The opening figure is total ever deposited, not what is left today</p><p>Enter <strong>every top-up ever sent to the carrier since the account was opened</strong>, not the balance the carrier shows now. The historical bookings and refunds are then replayed behind it to arrive at today&#39;s figure. Entering the <em>current remaining</em> balance instead double-counts the entire trading history.</p></div><h2 id="recording-a-top-up" tabindex="-1">Recording a top-up <a class="header-anchor" href="#recording-a-top-up" aria-label="Permalink to &quot;Recording a top-up&quot;">​</a></h2><p>Same endpoint, without <code>isOpeningBalance</code>.</p><p><code>amountSAR</code> is the SAR the carrier credited. It is entered by the admin and taken as authoritative — nothing here reads an exchange rate or converts a currency. If a top-up is wired in another currency, still enter the SAR the carrier credited and put the wire details in <code>note</code>.</p><p><code>reference</code> is the idempotency key. Submitting the same reference twice records nothing the second time rather than doubling the balance; the response&#39;s <code>created</code> field says which happened.</p><h2 id="replaying-history" tabindex="-1">Replaying history <a class="header-anchor" href="#replaying-history" aria-label="Permalink to &quot;Replaying history&quot;">​</a></h2><p><code>POST /api/v1/admin/supplier-ledger/replay</code></p><p>Run this once after the opening balance is recorded. It writes the debits and credits that predate the automatic hooks, so the balance is right the first time anyone reads it instead of showing a number that silently omits history.</p><p>Safe to run again at any time: every write is keyed on the movement, so anything already recorded is skipped rather than doubled.</p><p>It cannot recover what neither system records — see <em>What this cannot see</em>.</p><h2 id="reconciling-against-the-carrier" tabindex="-1">Reconciling against the carrier <a class="header-anchor" href="#reconciling-against-the-carrier" aria-label="Permalink to &quot;Reconciling against the carrier&quot;">​</a></h2><p>This is the important one, and the only thing that can tell you the balance has gone wrong.</p><p><strong>Step 1 — upload the export.</strong> Ask finance for the carrier account export (CSV) and upload it:</p><p><code>POST /api/v1/admin/supplier-ledger/reconcile/preview</code> (multipart, field <code>file</code>)</p><p>This <strong>writes nothing</strong>. It reports:</p><ul><li>PNRs the carrier charged that we hold no booking for</li><li>bookings we debited that the export never mentions</li><li>PNRs where the carrier&#39;s net and ours differ</li><li><code>rowsWithNoPnr</code> — export lines belonging to no booking, such as a top-up, so every line in the file is accounted for somewhere in the report</li></ul><p>The file is first checked against itself: its running <code>Balance</code> column must agree with the row-by-row sum. A file that does not add up is rejected, because it cannot be used to reconcile anything else.</p><p>Amounts are <strong>netted per PNR</strong>, never matched row to row. The carrier posts a <code>PURCHASE</code> for every ticketing attempt and auto-reverses the failures seconds later, so a booking that retried four times shows five purchases and four refunds. Only the net matters.</p><p>Each <code>perPnr</code> line also carries <code>carrierRows</code> and <code>ourEntries</code>: the lines that produced each net. They are there so a person looking at a difference can see what caused it — <strong>not</strong> to be paired up. The two sides can hold different numbers of rows, which is the same reason the nets are what get compared.</p><div class="tip custom-block"><p class="custom-block-title">Anything after the export&#39;s period end is not drift</p><p>The report includes <code>periodEnd</code>. A booking ticketed after that moment is simply outside the file, not a discrepancy.</p></div><p><strong>Step 2 — record the outcome.</strong></p><p><code>POST /api/v1/admin/supplier-ledger/reconcile</code></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;closingBalanceSAR&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">38449.46</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;asOf&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-09-03T09:34:19.000Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;reference&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;52783&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This writes one <code>RECONCILE</code> entry carrying the difference and moves our balance onto the carrier&#39;s. A second reconciliation against an unchanged ledger records zero rather than repeating the first.</p><p>The figure is supplied here, not read out of the upload, so that a file can never move the balance on its own.</p><h2 id="corrections" tabindex="-1">Corrections <a class="header-anchor" href="#corrections" aria-label="Permalink to &quot;Corrections&quot;">​</a></h2><p><code>POST /api/v1/admin/supplier-ledger/adjustments</code></p><p>For a carrier movement with no row on our side to derive it from. Two real examples:</p><ul><li>The carrier refunded a booking but our system never created a refund record, so nothing exists to credit from. Enter a <strong>positive</strong> adjustment.</li><li>The carrier kept a charge for a booking whose tickets were never issued. Enter a <strong>negative</strong> adjustment.</li></ul><p><code>reason</code> is required. An adjustment is the one place a person can move the balance with no external proof, so the reason, the recorded author, and the fact that rows are never edited are the whole audit trail.</p><h2 id="what-this-cannot-see" tabindex="-1">What this cannot see <a class="header-anchor" href="#what-this-cannot-see" aria-label="Permalink to &quot;What this cannot see&quot;">​</a></h2><p>Be honest with these numbers. The ledger is accounting, not detection.</p><ul><li><strong>A charge for a booking that never ticketed.</strong> If the carrier bills us and the booking never reaches <code>TICKETED</code>, there are no ticket numbers, no transition, and nothing in the carrier&#39;s per-booking API either. It exists only in the account export. Reconciliation is the only way to find it.</li><li><strong>A carrier refund we never recorded.</strong> Every automatic credit is derived from a refund record on our side, so a refund the carrier makes that we never wrote down is invisible here by construction.</li><li><strong>Reissue and change fees</strong>, if the carrier bills any.</li></ul><p>All three show up as reconciliation drift, but the report can only say the numbers disagree — it cannot always say which booking caused it.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Every code must be granted explicitly. No wildcard role picks them up, and there is deliberately no <code>supplier-ledger:*</code>.</p><table tabindex="0"><thead><tr><th>Code</th><th>Grants</th></tr></thead><tbody><tr><td><code>supplier-ledger:read-balance</code></td><td>View the balance and entries</td></tr><tr><td><code>supplier-ledger:deposit</code></td><td>Record the opening balance and top-ups</td></tr><tr><td><code>supplier-ledger:adjust</code></td><td>Record corrections</td></tr><tr><td><code>supplier-ledger:reconcile</code></td><td>Upload the export and record the outcome</td></tr><tr><td><code>supplier-ledger:backfill</code></td><td>Replay historical movements</td></tr></tbody></table><p>The read code is spelled <code>read-balance</code>, not <code>read</code>, on purpose: a role built as &quot;read-only, harmless&quot; must not come to hold our cost basis with the carrier. It follows the same rule as <code>invoices:read-supplier-cost</code>.</p>`,59)])])}const k=t(n,[["render",r]]);export{u as __pageData,k as default};
